intro:
Returns an iterator to the first element of the chunk_by_view.

Equivalent to:

ranges::iterator_t<V> iter;

if (begin_.has_value())
    iter = begin_.value();
else
{
    iter = /*find_next*/(ranges::begin(base()));
    begin_ = iter; // caching
}

return /*iterator*/(*this, ranges::begin(base()), iter);

The behavior is undefined if the underlying predicate pred_ does not contain a value.

examples.code:
#include <ranges>
#include <iterator>
#include <functional>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    int values[]{3, 5, 7, 9};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}, {3, 30}};
    auto view = std::ranges::chunk_by_view{values, std::less<>{}};
    auto position = view.begin();
    auto finish = view.end();
    assert(position != finish);
    (void)*position;
    auto copy = position;
    assert(copy == position);
    ++position;
    assert(position != copy);

    (void)std::ranges::iter_move(copy);

    assert(std::ranges::distance(view) > 0);
    std::cout << "Checks passed\n";
}
